import json

# Save the transform function to the Python file
transform_code = '''
def transform(graph):
    """
    Task-3b5f776f - ARC Puzzle Transform

    Rule:
    1. Find background color (most frequent in grid)
    2. Group non-background cells by their anti-diagonal (i + j = k)
    3. For each anti-diagonal that contains MULTIPLE different non-background colors:
       - Find the color whose cells reach HIGHEST row index (latest position)
       - Fill ALL background cells on that anti-diagonal with this color
    4. Anti-diagonals with only one non-background color are not extended
    """
    # Find background color (most common)
    all_cells = []
    for row in graph:
        all_cells.extend(row)
    bg = max(set(all_cells), key=all_cells.count)

    output = [row[:] for row in graph]

    # Track colors per anti-diagonal by: max row index and count
    adj_by_ij = {}
    adj_colors_count = {}

    for r in range(len(graph)):
        for c in range(len(graph[0])):
            val = graph[r][c]
            if val == bg:
                continue
            ij = r + c

            if ij not in adj_by_ij:
                adj_by_ij[ij] = {}
                adj_colors_count[ij] = {}

            # Track max row index for this color on this anti-diagonal
            if val not in adj_by_ij[ij]:
                adj_by_ij[ij][val] = r
            else:
                adj_by_ij[ij][val] = max(adj_by_ij[ij][val], r)

            # Track cell count
            if val not in adj_colors_count[ij]:
                adj_colors_count[ij][val] = 0
            adj_colors_count[ij][val] += 1

    # For each multi-color anti-diagonal, extend the "latest" (highest row) color
    for ij in adj_by_ij:
        colors_with_cells = list(adj_by_ij[ij].keys())
        if len(colors_with_cells) <= 1:
            continue

        # Multi-color anti-diagonal - find winner color
        winner_color = max(colors_with_cells, key=lambda c: adj_by_ij[ij][c])

        # Fill background cells on this anti-diagonal
        for r in range(len(graph)):
            c = ij - r
            if 0 <= c < len(graph[0]) and output[r][c] == bg:
                output[r][c] = winner_color

    return output
'''

